package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen2Test {

    private static final double DELTA = 1e-12;











    @Test
    public void testFactorialLog_LargeN() {
        // n >= 21 logic: uses the loop logSum += Math.log(i)
        int n = 25;
        double expectedLogSum = 0;
        for (int i = 2; i <= n; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(n), DELTA);
    }


}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen2Test {

    private static final double DELTA = 1e-12;













    @Test
    public void testFactorialLog_BoundaryN21() {
        // n = 21 is the first value to trigger the loop logic
        double expectedLogSum = 0;
        for (int i = 2; i <= 21; i++) {
            expectedLogSum += Math.log((double) i);
        }
        assertEquals(expectedLogSum, MathUtils.factorialLog(21), DELTA);
    }
}
